#!/usr/bin/env node
/**
 * generate-errors-doc - docs/errors.md, the page a failure's RFC 9457 `type`
 * resolves to: one section per condition (the `type` is `...errors.md#<condition>`),
 * each listing the ERROR_CODE_REGISTRY codes under it with their fix.
 *
 * Generated, committed, and regenerated by `npm run docs` (the gate diffs it),
 * so a code added to the registry appears here without anyone writing it.
 * The registry is read from the built `dist/` (the gate builds first). The
 * condition texts are the vocabulary table of docs/plan-failures-and-contract.md
 * 4.2; tests/problem-type.test.ts holds the anchors to the `Condition` type.
 */
import { writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const { ERROR_CODE_REGISTRY } = await import(pathToFileURL(join(root, 'dist', 'index.js')).href);

// condition -> [meaning, re-sent by default, gRPC / Connect]
const CONDITIONS = [
  ['missing', 'The thing is not there (404, 410; a handler not registered).', 'no', 'NOT_FOUND (a missing handler: UNIMPLEMENTED)'],
  ['already', 'It is there already.', 'no', 'ALREADY_EXISTS'],
  ['conflict', 'The state is not the one the request assumed (409, 412). Re-read, then decide.', 'no', 'ABORTED / FAILED_PRECONDITION'],
  ['invalid', 'Input broke a rule (any other 4xx).', 'no', 'INVALID_ARGUMENT / OUT_OF_RANGE'],
  ['refused', 'A rule or a party said no (403). Final.', 'no', 'PERMISSION_DENIED'],
  ['unauthenticated', 'No valid session or token (401, 419). Sign in, then send the same request.', 'no', 'UNAUTHENTICATED'],
  ['limited', 'A rate, a window or a circuit holds it back (429, 503). `context.retryIn` says when.', 'yes', 'RESOURCE_EXHAUSTED / UNAVAILABLE'],
  ['timeout', 'No reply in time (408, 504).', 'yes', 'DEADLINE_EXCEEDED'],
  ['lost', 'The outcome is unknown, or data was dropped: the command may or may not have run.', 'only when the command is idempotent or keyed', 'none (gRPC UNAVAILABLE is retry-safe, which this is not)'],
  ['aborted', 'The caller cancelled.', 'no', 'CANCELLED'],
  ['exceeded', 'A bound hit by a bug (recursion depth).', 'no', 'INTERNAL'],
  ['failed', 'Code threw or a step failed: a bug in the pipeline, or a backend\'s other 5xx.', 'never for a bug of the pipeline; a backend\'s only when the command is idempotent or keyed', 'INTERNAL'],
  ['unexpected', 'The other side answered off the protocol (501, 502, 505).', 'only when the command is idempotent or keyed', 'INTERNAL / UNKNOWN'],
  ['unknown', 'The fallback.', 'only when the command is idempotent or keyed', 'UNKNOWN'],
];

const out = [
  '# Failure conditions',
  '',
  '<!-- Generated by scripts/generate-errors-doc.mjs from ERROR_CODE_REGISTRY. Do not edit. -->',
  '',
  'Every failure the library raises is a `BusError` with the code',
  '`owner:condition:subject`. On the wire it is an RFC 9457 problem whose `type`',
  'is this page plus the condition (`.../errors.md#invalid`); the exact code is',
  'the `code` member. A backend\'s own `type` is kept. A plugin\'s throw is',
  '`<its id>:failed:plugin`; codes of your own plugins and of your backend are',
  'yours, and read by their condition below.',
  '',
];
for (const [c, meaning, retry, grpc] of CONDITIONS) {
  out.push(`<a id="${c}"></a>`, '', `## ${c}`, '', meaning, '', `Re-sent by the async bus by default: ${retry}. gRPC: ${grpc}.`, '');
  const codes = ERROR_CODE_REGISTRY.filter((e) => e.code.split(':')[1] === c);
  if (codes.length) {
    out.push('| code | severity | retryable | what | fix |', '|---|---|---|---|---|');
    for (const e of codes) out.push(`| \`${e.code}\` | ${e.severity} | ${e.retryable ? 'yes' : 'no'} | ${e.message.replaceAll('|', '\\|')} | ${e.fix.replaceAll('|', '\\|')} |`);
    out.push('');
  }
}
writeFileSync(join(root, 'docs', 'errors.md'), out.join('\n'));
